// XQL Chrome Extension — generated by xiaoqinli
'use strict';

function _xql_out(s) {
    var el = document.getElementById('output');
    if (el) el.textContent += s;
}

function _xql_str(v) {
    if (v === null || v === undefined) return 'null';
    if (Array.isArray(v)) return '[' + v.map(_xql_str).join(', ') + ']';
    if (typeof v === 'object' && typeof v.toString === 'function' && v.toString !== Object.prototype.toString) return v.toString();
    if (typeof v === 'object') return JSON.stringify(v);
    return String(v);
}

function _xql_print(v) {
    var s = _xql_str(v);
    _xql_out(s + '\n');
    console.log(v);
}

function _xql_printf(fmt) {
    var args = Array.prototype.slice.call(arguments, 1);
    var i = 0;
    var s = fmt.replace(/%[sdvf%]/g, function(m) { return m === '%%' ? '%' : (i < args.length ? _xql_str(args[i++]) : m); });
    _xql_out(s);
    console.log(s);
}

document.addEventListener('DOMContentLoaded', function() {
    try {
        if ((window.location.protocol === "chrome-extension:")) {
            _xql_print("======================================\n   ⚡ Xiaoqinli 极速音量放大器 v1.0   \n======================================\n\n【键盘快捷键使用指南】\n - 放大音量: 按住 Shift + 键盘向上键 (⬆️)\n - 减小音量: 按住 Shift + 键盘向下键 (⬇️)\n - 调节范围: 100% - 300% (每次调节 10%)\n\n--------------------------------------\n 本插件已自动注入到所有网页后台，无需保持此\n 弹窗打开即可使用！\n======================================");
        }
        let volume = 1;
        let audioCtx = "";
        let gainNode = "";
        let hudElement = "";
        let hudTimeout = "";
        const injectStyles = function() {
            const style = document.createElement("style");
            style.textContent = "\n        .xql-volume-hud {\n            position: fixed;\n            top: 20px;\n            right: 20px;\n            background: rgba(30, 30, 46, 0.95);\n            backdrop-filter: blur(8px);\n            border: 1px solid rgba(137, 180, 250, 0.25);\n            border-radius: 12px;\n            padding: 10px 16px;\n            color: #cdd6f4;\n            font-family: 'Outfit', 'Inter', system-ui, sans-serif;\n            font-size: 14px;\n            font-weight: 600;\n            z-index: 2147483647;\n            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);\n            display: flex;\n            align-items: center;\n            gap: 10px;\n            opacity: 0;\n            transform: translateY(-20px) scale(0.95);\n            transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n            pointer-events: none;\n        }\n        .xql-volume-hud.show {\n            opacity: 1;\n            transform: translateY(0) scale(1);\n        }\n        .xql-volume-progress-bg {\n            width: 100px;\n            height: 6px;\n            background: #313244;\n            border-radius: 3px;\n            overflow: hidden;\n        }\n        .xql-volume-progress-bar {\n            height: 100%;\n            background: linear-gradient(90deg, #89b4fa, #b4befe);\n            width: var(--vol-percent, 0%);\n            transition: width 0.1s ease;\n        }\n        .xql-volume-text {\n            min-width: 45px;\n            text-align: right;\n            color: #89b4fa;\n        }\n    ";
            document.head.appendChild(style);
        };
        const createHUD = function() {
            hudElement = document.createElement("div");
            hudElement.className = "xql-volume-hud";
            hudElement.innerHTML = "<span>🔊</span><div class=\"xql-volume-progress-bg\"><div class=\"xql-volume-progress-bar\" id=\"xql-vol-bar\"></div></div><span class=\"xql-volume-text\" id=\"xql-vol-text\">100%</span>";
            document.body.appendChild(hudElement);
        };
        const showBoosterUI = function(vol) {
            if (!hudElement) {
                createHUD();
            }
            const percent = Math.round((vol * 100));
            const bar = document.getElementById("xql-vol-bar");
            const text = document.getElementById("xql-vol-text");
            if (bar) {
                bar.style.setProperty("--vol-percent", (((percent - 100) / 2) + "%"));
            }
            if (text) {
                text.textContent = (percent + "%");
            }
            hudElement.classList.add("show");
            if (hudTimeout) {
                clearTimeout(hudTimeout);
            }
            hudTimeout = setTimeout(function() {
                hudElement.classList.remove("show");
            }, 1500);
        };
        const initAudio = function() {
            if (!audioCtx) {
                audioCtx = new window.AudioContext();
                gainNode = audioCtx.createGain();
                gainNode.gain.value = volume;
                gainNode.connect(audioCtx.destination);
            }
        };
        const connectMedia = function(media) {
            if (media.dataset) {
                if (!media.dataset.volumeBoosterConnected) {
                    const source = audioCtx.createMediaElementSource(media);
                    source.connect(gainNode);
                    media.dataset.volumeBoosterConnected = "true";
                }
            }
        };
        const applyVolume = function() {
            initAudio();
            gainNode.gain.value = volume;
            const mediaElements = document.querySelectorAll("video, audio");
            mediaElements.forEach(connectMedia);
            showBoosterUI(volume);
        };
        const adjustVolume = function(key) {
            if ((key === "ArrowUp")) {
                volume = (volume + 0.1);
                if ((volume > 3)) {
                    volume = 3;
                }
            } else {
                volume = (volume - 0.1);
                if ((volume < 1)) {
                    volume = 1;
                }
            }
            applyVolume();
        };
        const handleKeydown = function(event) {
            if (event.shiftKey) {
                if ((event.key === "ArrowUp")) {
                    event.preventDefault();
                    adjustVolume("ArrowUp");
                }
                if ((event.key === "ArrowDown")) {
                    event.preventDefault();
                    adjustVolume("ArrowDown");
                }
            }
        };
        injectStyles();
        document.addEventListener("keydown", handleKeydown);
    } catch (_err) {
        _xql_print('Error: ' + _err.message);
    }
});
